function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function icon(n){const p={back:'<path d="M19 12H5m6-6-6 6 6 6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',home:'<path d="m3 11 9-8 9 8v9h-6v-6H9v6H3z"/>',orders:'<path d="M7 4h10v16H7zM9 2h6v4H9zM10 10h4M10 14h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c1-5 15-5 16 0"/>',spark:'<path d="M12 3c0 5-2 7-7 7 5 0 7 2 7 7 0-5 2-7 7-7-5 0-7-2-7-7zM19 17v4m-2-2h4"/>',chev:'<path d="m9 6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M12 21s7-6 7-12a7 7 0 1 0-14 0c0 6 7 12 7 12z"/><circle cx="12" cy="9" r="2"/>',cart:'<path d="M3 4h2l2 11h10l3-8H6M9 20h.01M17 20h.01"/>',filter:'<path d="M4 5h16l-6 7v6l-4 2v-8z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',alert:'<path d="m12 3 9 17H3zM12 9v4M12 16h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M5 7h14M5 12h14M5 17h14"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',food:'<path d="M7 3v8a3 3 0 0 0 3-3V3M4 3v5m6-5v5M16 3v18m0-18c4 2 5 8 0 10"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3 2.4c-.5.2-.5.8-.5 1.6M12 17h.01"/>',logout:'<path d="M10 4H4v16h6M14 8l4 4-4 4M8 12h10"/>',edit:'<path d="m4 20 4-1 11-11-3-3L5 16zM14 6l3 3"/>',wifi:'<path d="M4 9a12 12 0 0 1 16 0M7 12a8 8 0 0 1 10 0M10 15a4 4 0 0 1 4 0M12 19h.01"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7M10 11v6M14 11v6"/>'};return `<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">${p[n]||p.info}</svg></span>`}
function status(type,text){return `<span class="status ${type}">${esc(text)}</span>`}
function statusBar(time='12.05'){return `<div class="statusbar"><span>${time}</span><span class="sys-icons"><i class="wifi"></i><i class="sig"></i><i class="battery"></i></span></div>`}
function appbar(title,right='',border=false){return `<div class="appbar ${border?'border':''}"><button class="icon-btn">${icon('back')}</button><h1>${title}</h1>${right||'<span style="width:48px"></span>'}</div>`}
function nav(role='student',active='home'){const items=role==='manager'?[['grid','Dashboard','dashboard'],['orders','Pesanan','orders'],['food','Menu','food'],['user','Profil','profile']]:[['home','Beranda','home'],['orders','Pesanan','orders'],['user','Profil','profile']];return `<nav class="bottom-nav">${items.map(([ic,l,k])=>`<button class="nav-item ${active===k?'active':''}">${icon(ic)}<span>${l}</span></button>`).join('')}</nav>`}
function shell(content,{time='12.05',navRole=null,active='home',cart=false,fab=false,coach=false,footer='',klass='',width=''}={}){return `<section class="screen ${klass} ${width}">${statusBar(time)}${content}${cart?cartBar():''}${footer}${navRole?nav(navRole,active):''}${fab?`<button class="fab ${cart?'with-cart-fab':''} ${coach?'pulse':''}" aria-label="Bantu pilih menu">${icon('spark')}</button>`:''}${coach?`<div class="coachmark"><strong>Bingung pilih?</strong><p>Aku bantu cari menu.</p><button class="icon-btn close" aria-label="Tutup">${icon('x')}</button></div>`:''}</section>`}
function cartBar(q='2 porsi',total='Rp30.000',standalone=false){return `<div class="sticky-cart ${standalone?'standalone':''}"><div><strong>${q} · ${total}</strong><small>Dapur Bu Rina</small></div><button class="btn">Lihat keranjang</button></div>`}
function searchBox(value='Cari menu atau stan',iconEnd=''){return `<div class="search">${icon('search')}<span>${value}</span>${iconEnd?`<span style="margin-left:auto">${icon(iconEnd)}</span>`:''}</div>`}
function menuRow(m,{qty=0,action=true,showStall=true,statusText=true,long=false,fallback=false,error=false}={}){const unavailable=m.status==='Habis';const act=!action?'':qty?`<div class="qty"><button>−</button><span>${qty}</span><button>+</button></div>`:`<button class="add-btn" ${unavailable?'disabled':''}>${unavailable?'Tidak tersedia':'Tambah'}</button>`;return `<div class="menu-row">${fallback?`<div class="photo-fallback">${icon('food')}</div>`:`<img class="menu-photo" src="${m.img}" alt="">`}<div class="menu-copy"><div class="menu-name">${long?'Nasi Ayam Sambal Matah dengan Lalapan Segar':m.name}</div>${showStall?`<div class="menu-sub">${m.stall} · ${m.time}</div>`:`<div class="menu-sub">${m.time}</div>`}<div class="menu-price">${m.price}</div>${statusText?`<div style="margin-top:4px">${status(unavailable?'rejected':'available',unavailable?'Habis':'Tersedia')}</div>`:''}${error?`<div class="helper" style="color:var(--danger)">Status belum berubah · <b>Coba lagi</b></div>`:''}</div><div class="menu-action">${act}</div></div>`}
function stallRow(name,loc){return `<div class="stall-row"><img class="stall-thumb" src="${name==='Dapur Bu Rina'?A+'stan-bu-rina.jpg':name==='Kedai Pak Ucok'?menu.mie.img:menu.geprek.img}" alt=""><div><strong>${name}</strong><div class="meta">${loc}</div><div style="margin-top:3px">${status('available','Buka')}</div></div>${icon('chev')}</div>`}
function home({cart=false,coach=false,offline=false,loading=false,failure=false,textScale=false,width=''}={}){if(loading)return loadingHome();if(failure)return emptyScreen('Menu belum dapat dimuat','Coba muat ulang sebentar lagi.','Coba lagi',{navRole:'student',active:'home'});let body=`<div class="scroll ${cart?'with-bar':''}"><div class="page ${textScale?'large-text':''}">${offline?`<div class="banner warning">${icon('wifi')}<div><strong>Koneksi terputus</strong><p>Data terakhir pukul 12.02 · Pemesanan dan asisten tidak tersedia.</p><button class="text-link">Coba lagi</button></div></div>`:''}<div class="meta">Kantin Kampus</div><div class="eyebrow">Halo, Doni</div><h2>Mau makan apa hari ini?</h2>${searchBox(offline?'Cari di data tersimpan':'Cari menu atau stan')}<div class="chips"><button class="chip active">Semua</button><button class="chip">Nasi</button><button class="chip">Mi</button><button class="chip">Camilan</button><button class="chip">Minuman</button></div><div class="section-head"><h3>Cepat jadi</h3><button class="text-link">Lihat semua</button></div>${menuRow(menu.ayam,{qty:cart?1:0})}${menuRow(menu.mie)}<div class="section-head"><h3>Stan yang buka</h3></div>${offline?stallRowOffline('Dapur Bu Rina','Blok A'):stallRow('Dapur Bu Rina','Blok A')}${offline?stallRowOffline('Kedai Pak Ucok','Blok B'):stallRow('Kedai Pak Ucok','Blok B')}${offline?stallRowOffline('Warung Sinta','Blok C'):stallRow('Warung Sinta','Blok C')}</div></div>`;return shell(body,{navRole:'student',active:'home',cart,fab:!offline,coach,width});}
function stallRowOffline(name,loc){return `<div class="stall-row"><img class="stall-thumb" src="${A+'stan-bu-rina.jpg'}"><div><strong>${name}</strong><div class="meta">${loc}</div><div class="caption">Status terakhir: Buka</div></div>${icon('chev')}</div>`}
function searchScreen({sheet=false,empty=false}={}){let content=`<div class="scroll"><div class="appbar"><button class="icon-btn">${icon('back')}</button><h1>Hasil pencarian</h1><span style="width:48px"></span></div><div class="page" style="padding-top:4px">${searchBox(empty?'sushi':'ayam','x')}<div class="chips"><button class="chip active">Maks. Rp20.000</button><button class="chip">${icon('filter')} Filter</button></div>${empty?`<div class="empty" style="height:520px">${emptyIcon('search')}<h3>Menu tidak ditemukan</h3><p>Coba ubah kata pencarian atau hapus filter.</p><button class="btn primary full">Ubah kata pencarian</button><button class="btn ghost full">Hapus filter</button></div>`:`<p class="meta" style="margin:14px 0 4px">3 menu ditemukan</p>${menuRow(menu.ayam)}${menuRow(menu.geprek)}${menuRow(menu.kecap)}</div>`}</div>`;content+=nav('student','home');if(sheet)content+=filterSheet();return shell(content);}
function filterSheet(){return `<div class="overlay"></div><div class="sheet medium"><div class="handle"></div><div class="sheet-title"><h3>Filter menu</h3><button class="icon-btn">${icon('x')}</button></div>${choiceGroup('Batas harga',['Maks. Rp15.000','Maks. Rp20.000','Tanpa batas'],1)}${choiceGroup('Waktu tunggu',['Maks. 10 menit','Maks. 20 menit','Tanpa batas'],0)}<div class="radio-row"><span class="radio selected"></span><span>Hanya menu tersedia</span></div><div class="spacer16"></div><button class="btn primary full">Terapkan filter</button><button class="btn ghost full">Reset</button></div>`}
function choiceGroup(label,choices,selected=0){return `<div class="form-group"><span class="form-label">${label}</span><div class="chips" style="padding:0">${choices.map((c,i)=>`<button class="chip ${i===selected?'active selected':''}">${c}</button>`).join('')}</div></div>`}
function stall({cart=false,closed=false,empty=false,width=''}={}){let rows=empty?`<div class="empty" style="height:350px">${emptyIcon('food')}<h3>Menu belum tersedia di stan ini</h3><p>Kamu bisa melihat pilihan dari stan lain.</p><button class="btn primary full">Lihat stan lain</button></div>`:[menuRow(menu.ayam,{qty:cart?1:0,showStall:false,action:!closed}),menuRow(menu.telur,{qty:cart?1:0,showStall:false,action:!closed}),menuRow(menu.sayur,{showStall:false,action:!closed}),menuRow(menu.teh,{showStall:false,action:!closed}),menuRow(menu.kecap,{showStall:false,action:!closed})].join('');let body=`<div class="scroll ${cart?'with-bar':''}">${appbar('Dapur Bu Rina')}<div class="page" style="padding-top:2px"><img class="hero" src="${A+'stan-bu-rina.jpg'}"><div class="stall-title"><div><h2>Dapur Bu Rina</h2><div class="info-line">${closed?status('rejected','Tutup'):status('available','Buka')}<span class="dot"></span><span class="meta">Kantin Kampus · Blok A</span><span class="meta">5–10 menit</span></div></div></div><p class="muted" style="margin-top:10px">Masakan rumahan, hangat setiap hari.</p>${closed?`<div class="banner warning" style="margin-top:12px">${icon('info')}<div><strong>Stan sedang tidak menerima pesanan</strong><p>Kamu masih bisa melihat menunya.</p></div></div>`:''}${searchBox('Cari menu di stan')}<div class="chips"><button class="chip active">Semua</button><button class="chip">Makanan</button><button class="chip">Minuman</button></div><div class="section-head"><h3>Menu</h3></div>${rows}</div></div>`;return shell(body,{navRole:'student',active:'home',cart,fab:!closed&&!empty,width});}
function detailMenu({added=false,sold=false}={}){
  const detailBody=sold
    ? `<div class="banner error" style="margin-top:18px">${icon('info')}<div><strong>Menu ini sedang habis</strong><p>Pilih menu lain dari Dapur Bu Rina.</p></div></div>`
    : `<div class="divider" style="margin:18px 0"></div><label class="form-label">Catatan untuk penjual (opsional)</label><div class="input muted">Sambal dipisah</div><div class="spacer12"></div><div class="summary-row"><strong>Jumlah</strong><div class="qty"><button>−</button><span>1</span><button>+</button></div></div>${added?`<div class="banner success" style="margin-top:14px">${icon('check')}<div><strong>Menu ditambahkan</strong><p>1 porsi menu ini di keranjang.</p></div></div><button class="text-link">Tambah lagi</button>`:''}`;
  const body=`<div class="scroll no-nav">${appbar('Detail menu')}<div class="page" style="padding-top:2px"><img class="hero" src="${A+'nasi-ayam-sambal-matah.jpg'}"><h2 style="margin:14px 0 4px">Nasi Ayam Sambal Matah</h2><div class="info-line"><strong style="color:var(--green);font-size:13px">Dapur Bu Rina</strong><span class="dot"></span><span class="meta">5–10 menit</span>${sold?status('rejected','Habis'):status('available','Tersedia')}</div><div class="menu-price" style="font-size:18px;margin:8px 0">Rp18.000</div><p class="muted">Nasi hangat, ayam suwir, sambal matah, dan lalapan segar.</p>${detailBody}</div></div>`;
  const footer=sold?`<div class="footer-cta"><button class="btn primary full">Lihat menu lain dari stan ini</button></div>`:added?cartBar('2 porsi','Rp30.000',true):`<div class="footer-cta"><div class="total"><small>1 porsi</small><strong>Rp18.000</strong></div><button class="btn primary">Tambah ke keranjang</button></div>`;
  return shell(body,{footer});
}
function assistant(type='base'){let keyboard=type==='keyboard';let fail=type==='fail';let clarify=type==='clarify';let inner;if(fail)inner=`<div class="banner error">${icon('alert')}<div><strong>Asisten sedang bermasalah</strong><p>Kamu tetap bisa mencari menu secara manual.</p></div></div><div class="order-summary"><div class="meta">Pilihan tersimpan</div><div class="summary-row"><span>Maks. Rp20.000</span><span>Maks. 10 menit</span></div></div><div class="spacer16"></div><button class="btn primary full">Coba lagi</button><button class="btn ghost full">Cari menu sendiri</button>`;else if(clarify)inner=`<div class="banner"><div><span class="caption">Kebutuhanmu</span><strong>Yang murah dan cepat</strong></div></div><h3>Batas harga yang kamu inginkan?</h3>${choiceGroup('', ['Maks. Rp15.000','Maks. Rp20.000','Tanpa batas'],1)}<button class="btn primary full">Tampilkan rekomendasi</button><button class="btn ghost full">Ubah kebutuhan</button>`;else inner=`<p class="muted">Pilih kebutuhanmu, aku bantu cari menu.</p>${choiceGroup('Batas harga',['Maks. Rp15.000','Maks. Rp20.000','Tanpa batas'],1)}${choiceGroup('Waktu tunggu',['Maks. 10 menit','Maks. 20 menit','Tanpa batas'],0)}${choiceGroup('Selera',['Tidak pedas','Pakai nasi','Berkuah'],0)}<label class="form-label" style="margin-top:14px">Pilihan lain (opsional)</label><div class="input ${keyboard?'active':''}">${keyboard?'Ingin makan sebelum kelas':'Tulis pilihan lain…'}</div><div class="spacer12"></div><button class="btn primary full">Cari rekomendasi</button><button class="btn ghost full">Nanti saja</button>`;let base=`<div class="scroll">${homeInner()}</div>${nav('student','home')}<div class="overlay"></div><div class="sheet ${keyboard?'keyboard':'tall'}"><div class="handle"></div><div class="sheet-title">${icon('spark')}<h3>Bantu pilih menu</h3><button class="icon-btn">${icon('x')}</button></div>${inner}</div>${keyboard?keyboardUI():''}`;return shell(base);}
function homeInner(){return `<div class="page"><div class="meta">Kantin Kampus</div><div class="eyebrow">Halo, Doni</div><h2>Mau makan apa hari ini?</h2>${searchBox()}<div class="chips"><button class="chip active">Semua</button><button class="chip">Nasi</button><button class="chip">Mi</button><button class="chip">Minuman</button></div>${menuRow(menu.ayam)}${menuRow(menu.mie)}</div>`}
function keyboardUI(){const rows=['Q W E R T Y U I O P','A S D F G H J K L','⇧ Z X C V B N M ⌫'];return `<div class="keyboard-panel">${rows.map(r=>`<div class="key-row">${r.split(' ').map(k=>`<span class="key">${k}</span>`).join('')}</div>`).join('')}<div class="key-row"><span class="key">123</span><span class="key space"></span><span class="key">↵</span></div></div>`}
function recommendations({cart=false,empty=false,long=false}={}){let body=`<div class="scroll ${cart?'with-bar':'no-nav'}">${appbar('Rekomendasi untukmu',`<button class="icon-btn">${icon('edit')}</button>`)}<div class="page"><div class="caption">Pilihanmu</div><p style="margin-top:3px">Maks. Rp20.000 · Maks. 10 menit</p><button class="text-link">Ubah pilihan</button>${cart?`<div class="banner">${icon('cart')}<div><strong>Keranjangmu dari Dapur Bu Rina</strong><p>2 porsi · Rp30.000</p></div></div>`:''}${empty?`<div class="empty" style="height:470px">${emptyIcon('search')}<h3>Belum ada menu yang cocok</h3><p>Coba longgarkan batas harga atau waktu tunggu.</p><button class="btn primary full">Ubah pilihan</button><button class="btn ghost full">Lihat semua menu</button></div>`:`<div class="section-head"><h3>3 menu paling cocok</h3></div>${menuRow(menu.ayam,{qty:cart?1:0,long})}${menuRow(menu.telur,{qty:cart?1:0})}${menuRow(menu.mie)}</div>`}</div>`;return shell(body,{footer:cart?cartBar('2 porsi','Rp30.000',true):''});}
function cartItem(m,{note='',qty=1,unavailable=false}={}){return `<div class="cart-item"><img src="${m.img}"><div><h4>${m.name}</h4><div class="price">${m.price}</div>${note?`<div class="helper">Catatan: ${note}</div>`:''}${unavailable?`<div style="margin-top:5px">${status('rejected','Habis')}</div>`:''}<div class="cart-actions"><button class="small-action">Ubah catatan</button><button class="small-action" style="color:var(--danger)">Hapus</button></div></div><div class="qty"><button>−</button><span>${qty}</span><button>+</button></div></div>`}
function cart({one=false,unavailable=false,long=false,keyboard=false}={}){let total=one?'Rp18.000':long?'Rp94.000':'Rp30.000';let items=long?`${cartItem(menu.ayam,{note:'Sambal dipisah, lalapan dibungkus terpisah',qty:3})}${cartItem(menu.telur,{qty:2})}${cartItem(menu.teh,{note:'Es sedikit',qty:2})}${cartItem({...menu.sayur,status:'Tersedia'},{qty:1})}`:`${cartItem(menu.ayam,{note:'Sambal dipisah'})}${one?'':cartItem(menu.telur,{unavailable})}`;let body=`<div class="scroll no-nav">${appbar('Keranjang',`<button class="text-link" style="color:var(--danger)">Kosongkan</button>`)}<div class="page" style="padding-top:4px">${unavailable?`<div class="banner error">${icon('alert')}<div><strong>Ada menu yang sudah habis</strong><p>Tinjau perubahan sebelum melanjutkan.</p></div></div>`:''}<h3 style="margin-top:8px">Dapur Bu Rina</h3><p class="meta">Pesanan dari satu stan</p>${items}${unavailable?`<button class="btn destructive-outline full" style="margin-top:12px">Hapus menu habis</button>`:''}<div class="form-group"><label class="form-label">Catatan pesanan</label><div class="input ${keyboard?'active':''}">${long||keyboard?'Bungkus terpisah. Tolong beri label pada setiap bungkus.':'Bungkus terpisah'}</div></div><div class="summary-row"><span>${unavailable?'Total menu tersedia':'Subtotal'}</span><strong>${unavailable?'Rp18.000':total}</strong></div><div class="summary-row total"><span>Total</span><strong>${unavailable?'Rp18.000':total}</strong></div><p class="caption">Tunai saat mengambil di stan</p></div></div>`;let footer=`<div class="footer-cta"><div class="total"><small>${long?'8 porsi · 4 jenis menu':one?'1 porsi':'2 porsi'}</small><strong>${unavailable?'Rp18.000':total}</strong></div><button class="btn ${unavailable?'disabled':'primary'}">${unavailable?'Tinjau perubahan':'Lanjut konfirmasi'}</button></div>`;return shell(body,{footer:keyboard?'':footer});}
function cartOverlay(type){let base=cart();let overlay=type==='edit'?`<div class="overlay"></div><div class="sheet keyboard" style="height:300px"><div class="handle"></div><div class="sheet-title"><h3>Catatan untuk Nasi Ayam Sambal Matah</h3><button class="icon-btn">${icon('x')}</button></div><label class="form-label">Catatan <span class="caption">(Opsional)</span></label><div class="input active">Sambal dipisah</div><div class="spacer12"></div><button class="btn primary full">Simpan catatan</button><button class="btn ghost full">Batal</button></div>${keyboardUI()}`:type==='clear'?dialog('Kosongkan keranjang?','2 porsi dari Dapur Bu Rina akan dihapus.','Tetap simpan','Kosongkan',true):'';return base.replace('</section>',overlay+'</section>')}
function changeStall(){let base=recommendations({cart:true});let d=dialog('Ganti isi keranjang?','Keranjangmu berisi 2 porsi dari Dapur Bu Rina (Rp30.000). Untuk menambah Mi Gomak dari Kedai Pak Ucok (Rp15.000), isi saat ini akan dihapus.','Tetap di Bu Rina','Ganti ke Pak Ucok',true);return base.replace('</section>',d+'</section>')}
function dialog(title,copy,safe,danger,isDanger=false){return `<div class="overlay"></div><div class="dialog-wrap"><div class="dialog"><h3>${title}</h3><p class="muted">${copy}</p><div class="dialog-actions"><button class="btn ghost">${safe}</button><button class="btn ${isDanger?'destructive':'primary'}">${danger}</button></div></div></div>`}
function emptyCart(){return shell(`<div class="scroll no-nav">${appbar('Keranjang')}<div class="page"><div class="empty">${emptyIcon('cart')}<h3>Keranjangmu masih kosong</h3><p>Pilih menu dari stan yang kamu inginkan.</p><button class="btn primary full">Cari menu</button></div></div></div>`)}
function checkout(type='valid'){let loading=type==='loading',failed=type==='failed',unknown=type==='unknown';let body=`<div class="scroll no-nav">${appbar('Konfirmasi pesanan')}<div class="page"><h2>Periksa pesananmu</h2>${failed?`<div class="banner error">${icon('alert')}<div><strong>Pesanan belum terkirim</strong><p>Coba lagi setelah koneksi membaik.</p></div></div>`:''}${unknown?`<div class="banner warning">${icon('wifi')}<div><strong>Memeriksa pesananmu</strong><p>Koneksi terputus saat mengirim. Periksa status pengiriman sebelum mencoba lagi.</p></div></div>`:''}<h3>Ambil di</h3><div class="location-box">${icon('pin')}<div><strong>Dapur Bu Rina</strong><p class="meta">Kantin Kampus · Blok A</p></div></div><h3>Ringkasan</h3><div class="order-summary"><div class="summary-row"><span>Nasi Ayam Sambal Matah ×1<br><small class="muted">Sambal dipisah</small></span><strong>Rp18.000</strong></div><div class="summary-row"><span>Nasi Telur Dadar ×1</span><strong>Rp12.000</strong></div><div class="summary-row total"><span>Total</span><strong>Rp30.000</strong></div></div><h3>Pembayaran</h3><div class="location-box">${icon('food')}<div><strong>Tunai di konter</strong><p class="meta">Bayar saat mengambil pesanan</p></div></div><p class="caption">Estimasi penyajian 5–10 menit setelah pesanan diterima.</p></div></div>`;let label=loading?'Membuat pesanan…':failed?'Coba kirim lagi':unknown?'Periksa status pengiriman':'Buat pesanan';return shell(body,{footer:`<div class="footer-cta"><button class="btn ${loading?'disabled':'primary'} full">${loading?'<span class="loading-dot"></span>':''}${label}</button></div>`});}
function success(){return shell(`<div class="scroll flush"><div class="page"><div class="empty" style="height:810px;justify-content:flex-start;padding-top:90px">${emptyIcon('check','success')}<h2 style="margin-bottom:4px">Pesanan dibuat</h2>${status('waiting','Menunggu konfirmasi')}<div style="font-size:36px;font-weight:800;color:var(--action);margin:24px 0 14px">KC-027</div><div class="order-summary" style="width:100%;text-align:left"><div class="summary-row"><span>Dapur Bu Rina</span><strong>Blok A</strong></div><div class="summary-row"><span>Dibuat</span><strong>12.05</strong></div><div class="summary-row"><span>2 porsi</span><strong>Rp30.000</strong></div><div class="summary-row"><span>Pembayaran</span><strong>Tunai di konter</strong></div></div><p style="margin:18px 0">Stan akan mengonfirmasi pesananmu. Tunggu status Siap diambil sebelum ke konter.</p><button class="btn primary full">Pantau pesanan</button><button class="btn ghost full">Kembali ke beranda</button></div></div></div>`)}
function studentOrders({history=false,empty=false,loading=false}={}){let content=`<div class="scroll"><div class="page" style="padding-top:8px"><h2>Pesanan</h2><div class="tabs"><button class="tab ${!history?'active':''}">Aktif</button><button class="tab ${history?'active':''}">Riwayat</button></div>${loading?orderSkeleton():empty?`<div class="empty" style="height:520px">${emptyIcon('orders')}<h3>${history?'Belum ada riwayat pesanan':'Belum ada pesanan aktif'}</h3><p>${history?'Pesanan yang selesai akan muncul di sini.':'Cari menu untuk membuat pesanan baru.'}</p>${history?'':'<button class="btn primary full">Cari menu</button>'}</div>`:history?`${orderRow('KC-027','Dapur Bu Rina','2 porsi · Rp30.000','Selesai · 12.20','done')} ${orderRow('KC-019','Dapur Bu Rina','1 porsi · Rp18.000','Selesai · 3 Sep','done')}`:`${orderRow('KC-027','Dapur Bu Rina','2 porsi · Rp30.000','Menunggu konfirmasi','waiting')}<div class="banner" style="margin-top:12px">${icon('clock')}<div><strong>Menunggu konfirmasi stan</strong><p>Dibuat pukul 12.05 · Lihat detail</p></div></div>`}</div></div>`;return shell(content,{navRole:'student',active:'orders'});}
function orderRow(id,name,metaText,state,stateType,queue=''){return `<div class="order-row"><div class="order-row-head">${queue?`<span class="queue-number">${queue}</span>`:''}<div style="flex:1"><h4>${id} · ${name}</h4></div>${status(stateType,state)}</div><div class="order-meta"><span>${metaText}</span><strong>Lihat detail</strong></div></div>`}
function studentDetail(state='waiting',error=false){const map={waiting:['Menunggu konfirmasi','waiting','Pesananmu sedang menunggu konfirmasi stan.','12.06'],process:['Diproses','process','Pesanan sedang disiapkan · perkiraan 5–10 menit sejak diterima.','12.08'],ready:['Siap diambil','ready','Tunjukkan nomor pesanan ini. Bayar tunai Rp30.000 saat mengambil.','12.15'],done:['Selesai','done','Pesanan sudah diambil dan dibayar di konter.','12.20'],rejected:['Ditolak','rejected','Pesanan tidak diproses. Tidak ada pembayaran yang perlu dilakukan.','12.06']};let [txt,type,copy,time]=map[state];let steps=state==='rejected'?[['Pesanan dibuat','12.05','complete'],['Ditolak','Menu tidak tersedia','rejected']]:[['Pesanan dibuat','12.05','complete'],['Diproses',state==='waiting'?'': '12.07',state==='waiting'?'': 'complete'],['Siap diambil',state==='ready'||state==='done'?'12.15':'',state==='ready'||state==='done'?'complete':''],['Selesai',state==='done'?'12.20':'',state==='done'?'complete':'']];return shell(`<div class="scroll no-nav">${appbar('Status pesanan')}<div class="page"><div class="order-row-head"><div><span class="caption">KC-027 · Dapur Bu Rina</span><h2 style="margin:3px 0 8px">${state==='ready'?'KC-027':txt}</h2></div>${status(type,txt)}</div>${error?`<div class="banner error">${icon('wifi')}<div><strong>Status belum dapat diperbarui</strong><p>Terakhir diperbarui pukul 12.08</p><button class="text-link">Muat ulang</button></div></div>`:`<div class="banner ${type==='ready'?'success':type==='rejected'?'error':''}">${icon(type==='rejected'?'alert':'info')}<div><strong>${txt}</strong><p>${copy}</p></div></div>`}<div class="caption">Diperbarui pukul ${time}</div><h3>Perjalanan pesanan</h3><div class="timeline">${steps.map(s=>`<div class="time-step ${s[2]}"><span class="time-dot">${s[2]?'✓':''}</span><div><strong>${s[0]}</strong><small>${s[1]}</small></div></div>`).join('')}</div><h3>Ringkasan</h3><div class="order-summary"><div class="summary-row"><span>Nasi Ayam Sambal Matah ×1</span><strong>Rp18.000</strong></div><div class="summary-row"><span>Nasi Telur Dadar ×1</span><strong>Rp12.000</strong></div><div class="summary-row total"><span>Total</span><strong>Rp30.000</strong></div></div><div class="location-box" style="margin-top:12px">${icon('pin')}<div><strong>Dapur Bu Rina · Blok A</strong><p class="meta">Bayar tunai saat mengambil</p></div></div></div></div>`,{time});}
function profile(manager=false){let rows=manager?[['user','Data akun'],['food','Pengaturan stan'],['bell','Notifikasi pesanan'],['help','Bantuan'],['info','Tentang KantinCerdas']]:[['orders','Riwayat pesanan'],['food','Preferensi makanan'],['bell','Notifikasi pesanan'],['help','Bantuan'],['info','Tentang KantinCerdas']];return shell(`<div class="scroll"><div class="page"><h2>Profil</h2><div class="profile-head"><div class="avatar">${manager?'BR':'D'}</div><strong>${manager?'Bu Rina':'Doni'}</strong><p class="meta">${manager?'Pengelola Dapur Bu Rina · rina@example.com':'doni@example.com'}</p><span class="mode">Mode demo</span></div>${rows.map(r=>`<div class="settings-row">${icon(r[0])}<span>${r[1]}</span>${icon('chev')}</div>`).join('')}<div class="settings-row" style="color:var(--danger);margin-top:12px">${icon('logout')}<span>Keluar</span>${icon('chev')}</div><p class="caption" style="text-align:center;margin-top:20px">Versi demo</p></div></div>`,{navRole:manager?'manager':'student',active:'profile'});}
function preferences(saved=false){let body=`<div class="scroll no-nav">${appbar('Preferensi makanan')}<div class="page"><p class="muted">Pilihan ini membantu asisten memberi rekomendasi yang lebih sesuai.</p>${choiceGroup('Selera',['Pedas','Tidak pedas','Berkuah','Pakai nasi'],1)}<div class="form-group"><span class="form-label">Batas harga pilihan</span>${radioOptions(['Maks. Rp15.000','Maks. Rp20.000','Tanpa batas'],1)}</div><div class="form-group"><span class="form-label">Waktu tunggu</span>${radioOptions(['Maks. 10 menit','Maks. 20 menit','Tanpa batas'],0)}</div></div></div>`;let out=shell(body,{footer:`<div class="footer-cta"><button class="btn primary full">Simpan preferensi</button></div>`});return saved?out.replace('</section>',`<div class="snackbar"><span>Preferensi disimpan</span>${icon('check')}</div></section>`):out}
function radioOptions(arr,sel=0){return arr.map((x,i)=>`<div class="radio-row"><span class="radio ${i===sel?'selected':''}"></span><span>${x}</span></div>`).join('')}
function emptyIcon(ic,kind=''){return `<div class="empty-icon" ${kind==='success'?'style="background:var(--green-bg);color:var(--green)"':''}>${icon(ic)}</div>`}

function dashboard(closed=false,dialogOpen=false){let content=`<div class="scroll"><div class="page"><div class="meta">Dapur Bu Rina</div><h2>Selamat siang, Bu Rina</h2><div class="location-box"><div style="flex:1"><strong>${closed?'Stan tutup':'Stan buka'}</strong><p class="meta">${closed?'Tidak menerima pesanan baru':'Menerima pesanan baru'}</p></div><div class="switch ${closed?'':'on'}"><span></span></div></div><h3>Ringkasan hari ini</h3><div class="dashboard-cards"><div class="metric"><strong>24</strong><small>Pesanan</small></div><div class="metric"><strong>3</strong><small>Menunggu</small></div><div class="metric"><strong>2</strong><small>Diproses</small></div><div class="metric"><strong>1</strong><small>Siap</small></div></div><p class="caption" style="margin-top:8px">18 pesanan selesai</p><h3>Perlu tindakan</h3><div class="action-row"><div class="icon-tile">${icon('orders')}</div><div class="copy"><strong>3 pesanan baru</strong><span class="caption">Urutkan dari yang paling lama</span></div><button class="text-link">Lihat pesanan</button></div><div class="action-row"><div class="icon-tile">${icon('food')}</div><div class="copy"><strong>2 menu berstatus habis</strong><span class="caption">Sayur Asem dan Nasi Ayam Kecap</span></div><button class="text-link">Kelola menu</button></div><h3>Antrean terbaru</h3>${orderRow('KC-027','Doni','2 porsi · Rp30.000','Menunggu','waiting','1')}${orderRow('KC-028','Ayu','1 porsi · Rp18.000','Menunggu','waiting','2')}${orderRow('KC-029','Bima','2 porsi · Rp24.000','Menunggu','waiting','3')}</div></div>${nav('manager','dashboard')}`;let out=shell(content);return dialogOpen?out.replace('</section>',dialog('Tutup stan sementara?','Pesanan baru tidak dapat dibuat. Pesanan yang sudah masuk tetap perlu ditangani. Antrean aktif: 6 pesanan.','Tetap buka','Tutup stan')+'</section>'):out}
function managerOrders(tab='new',empty=false,offline=false,error=false){let heading={new:'Menunggu konfirmasi',process:'Sedang diproses',ready:'Siap diambil',history:'Riwayat pesanan'}[tab];let rows='';if(tab==='new')rows=orderRow('KC-027','Doni','2 porsi · Rp30.000','12.05','waiting','1')+orderRow('KC-028','Ayu','1 porsi · Rp18.000','12.05','waiting','2')+orderRow('KC-029','Bima','2 porsi · Rp24.000','12.06','waiting','3');if(tab==='process')rows=orderRow('KC-025','Raka','1 porsi · Rp12.000','Mulai 11.58','process')+orderRow('KC-026','Sari','1 porsi · Rp18.000','Mulai 12.01','process');if(tab==='ready')rows=orderRow('KC-024','Dita','2 porsi · Rp23.000','Siap 12.03','ready');if(tab==='history')rows=`<div class="chips"><button class="chip active">Semua</button><button class="chip">Selesai</button><button class="chip">Ditolak</button></div>${orderRow('KC-027','Doni','Rp30.000 · 6 Sep, 12.20','Selesai','done')}${orderRow('KC-018','Rani','Rp12.000 · 5 Sep, 13.10','Ditolak','rejected')}`;let center=error?`<div class="empty" style="height:510px">${emptyIcon('alert')}<h3>Pesanan belum dapat dimuat</h3><p>Ada gangguan sementara. Coba muat ulang.</p><button class="btn primary full">Coba lagi</button><button class="btn ghost full">Kembali ke dashboard</button></div>`:empty?`<div class="empty" style="height:510px">${emptyIcon('orders')}<h3>Belum ada pesanan baru</h3><p>Pesanan baru akan muncul di sini.</p></div>`:rows;return shell(`<div class="scroll"><div class="page" style="padding-top:8px">${offline?`<div class="banner warning">${icon('wifi')}<div><strong>Offline · Data terakhir pukul 12.06</strong><p>Antrean dapat dibaca. Perubahan status dinonaktifkan.</p><button class="text-link">Coba lagi</button></div></div>`:''}<h2>Pesanan</h2><div class="tabs"><button class="tab ${tab==='new'?'active':''}">Baru 3</button><button class="tab ${tab==='process'?'active':''}">Diproses 2</button><button class="tab ${tab==='ready'?'active':''}">Siap 1</button><button class="tab ${tab==='history'?'active':''}">Riwayat</button></div><div class="section-head"><h3>${heading}</h3></div>${tab==='new'&&!error&&!empty?'<p class="caption">Yang paling lama menunggu di atas</p>':''}${center}</div></div>`,{navRole:'manager',active:'orders'});}
function managerDetail(state='new',modal=''){const config={new:['Menunggu konfirmasi','waiting','Dibuat pukul 12.05'],process:['Diproses','process','Diterima pukul 12.07'],ready:['Siap diambil','ready','Siap pukul 12.15'],done:['Selesai','done','Selesai pukul 12.20'],rejected:['Ditolak','rejected','Ditolak pukul 12.06']}[state];let body=`<div class="scroll no-nav">${appbar('KC-027')}<div class="page"><div class="order-row-head"><div><h2 style="margin:0">Doni</h2><p class="meta">${config[2]}</p></div>${status(config[1],config[0])}</div>${state==='ready'?`<div class="banner success" style="margin-top:14px">${icon('check')}<div><strong>KC-027 siap diambil</strong><p>Cocokkan nomor pesanan sebelum menyerahkan makanan.</p></div></div>`:''}${state==='rejected'?`<div class="banner error" style="margin-top:14px">${icon('alert')}<div><strong>Menu tidak tersedia</strong><p>Alasan ini telah ditampilkan kepada mahasiswa.</p></div></div>`:''}<h3>Item pesanan</h3>${cartItem(menu.ayam,{note:'Sambal dipisah'})}${cartItem(menu.telur)}<div class="form-group"><span class="form-label">Catatan pesanan</span><p>Bungkus terpisah</p></div><div class="summary-row"><span>Pembayaran</span><strong>${state==='done'?'Tunai diterima':state==='rejected'?'Tidak ditagihkan':'Tunai saat mengambil · belum dibayar'}</strong></div><div class="summary-row total"><span>Total</span><strong>Rp30.000</strong></div></div></div>`;let footer='';if(state==='new')footer=`<div class="footer-cta"><button class="btn destructive-outline" style="min-width:105px">Tolak</button><button class="btn primary" style="flex:1">Terima & siapkan</button></div>`;if(state==='process')footer=`<div class="footer-cta"><button class="btn primary full">Tandai siap diambil</button></div>`;if(state==='ready')footer=`<div class="footer-cta"><button class="btn primary full">Selesaikan pesanan</button></div>`;if(state==='done'||state==='rejected')footer=`<div class="footer-cta"><button class="btn primary full">Kembali ke pesanan</button></div>`;let out=shell(body,{footer,time:state==='done'?'12.20':state==='ready'?'12.15':state==='process'?'12.08':'12.06'});if(modal==='finish')out=out.replace('</section>',dialog('Selesaikan pesanan KC-027?','Pastikan makanan sudah diserahkan kepada Doni dan pembayaran tunai Rp30.000 sudah diterima.','Belum selesai','Ya, selesaikan')+'</section>');if(modal==='reject')out=out.replace('</section>',`<div class="overlay"></div><div class="sheet medium"><div class="handle"></div><div class="sheet-title"><h3>Tolak pesanan KC-027?</h3><button class="icon-btn">${icon('x')}</button></div><p class="muted">Alasan ini akan ditampilkan kepada mahasiswa.</p><div class="order-summary" style="margin:12px 0"><div class="summary-row"><span>Doni · 2 porsi</span><strong>Rp30.000</strong></div></div>${radioOptions(['Menu tidak tersedia','Stan tidak dapat memproses','Lainnya'],0)}<div class="spacer12"></div><button class="btn destructive full">Tolak pesanan</button><button class="btn ghost full">Batal</button></div></section>`);return out}
function managerMenu(error=false,empty=false){let rows=empty?`<div class="empty" style="height:470px">${emptyIcon('search')}<h3>Tidak ada menu yang sesuai filter</h3><p>Ubah atau hapus filter untuk melihat menu.</p><button class="btn primary full">Reset filter</button></div>`:[menuRow(menu.ayam,{action:false}),menuRow(menu.telur,{action:false}),menuRow(menu.sayur,{action:false,error}),menuRow(menu.teh,{action:false}),menuRow(menu.kecap,{action:false})].join('').replaceAll('<div class="menu-action"></div>',`<div class="menu-action"><div class="switch on"><span></span></div></div>`);if(!empty){let idx=0;rows=rows.replaceAll('<div class="switch on">',()=>`<div class="switch ${(++idx===3||idx===5)?'':'on'}">`)}return shell(`<div class="scroll"><div class="page" style="padding-top:8px"><h2>Menu</h2>${searchBox('Cari menu')}<div class="chips"><button class="chip active">Semua</button><button class="chip">Tersedia</button><button class="chip">Habis</button></div>${rows}</div></div>`,{navRole:'manager',active:'food'});}
function settings(error=false){return shell(`<div class="scroll no-nav">${appbar('Pengaturan stan')}<div class="page"><img class="hero" src="${A+'stan-bu-rina.jpg'}"><h2 style="margin:14px 0 4px">Dapur Bu Rina</h2><p class="muted">Masakan rumahan, hangat setiap hari.</p><div class="location-box" style="margin-top:14px">${icon('pin')}<div><strong>Kantin Kampus · Blok A</strong><p class="meta">Informasi stan hanya-baca</p></div></div>${error?`<div class="banner error">${icon('alert')}<div><strong>Perubahan belum tersimpan</strong><p>Coba lagi. Pilihanmu tetap tersedia di halaman ini.</p></div></div>`:''}<h3>Status stan manual</h3><div class="action-row"><div class="copy"><strong>Stan buka</strong><span class="caption">Menerima pesanan baru</span></div><div class="switch on"><span></span></div></div><h3>Estimasi penyajian</h3><div class="chips"><button class="chip active selected">5–10 menit</button><button class="chip">10–15 menit</button><button class="chip">15–20 menit</button></div><h3>Jadwal informasi</h3><div class="order-summary"><div class="summary-row"><span>Senin–Jumat</span><strong>08.00–16.00</strong></div></div><p class="helper">Penerimaan pesanan diatur melalui status buka/tutup.</p></div></div>`,{footer:`<div class="footer-cta"><button class="btn primary full">${error?'Coba simpan lagi':'Simpan perubahan'}</button></div>`});}
function notification(kind='intro'){if(kind==='intro'){let base=success();return base.replace('</section>',`<div class="overlay"></div><div class="sheet" style="height:390px"><div class="handle"></div><div class="sheet-title">${icon('bell')}<h3>Ingin mendapat kabar saat pesanan siap?</h3><button class="icon-btn">${icon('x')}</button></div><p class="muted">Aktifkan notifikasi agar perubahan status lebih mudah diketahui.</p><div class="spacer24"></div><button class="btn primary full">Aktifkan notifikasi</button><button class="btn ghost full">Nanti saja</button><p class="caption" style="text-align:center;margin-top:14px">Status tetap bisa dilihat di halaman Pesanan.</p></div></section>`)}let active=kind==='active';return shell(`<div class="scroll no-nav">${appbar('Notifikasi pesanan')}<div class="page"><div class="empty" style="height:310px;justify-content:flex-start;padding-top:36px">${emptyIcon('bell',active?'success':'')}<h3>${active?'Notifikasi pesanan aktif':'Notifikasi belum diizinkan'}</h3><p>${active?'Izin perangkat diaktifkan. Kamu akan mendapat kabar saat status pesanan berubah.':'Izin notifikasi untuk KantinCerdas dinonaktifkan di perangkat.'}</p></div>${active?`<div class="action-row"><div class="copy"><strong>Notifikasi pesanan</strong><span class="caption">Aktif di aplikasi</span></div><div class="switch on"><span></span></div></div>`:`<button class="btn primary full">Buka pengaturan perangkat</button><p class="helper" style="text-align:center">Status pesanan tetap bisa dilihat di halaman Pesanan.</p>`}</div></div>`)}
function support(type){if(type==='help')return infoPage('Bantuan',`<p class="muted">Temukan jawaban singkat tentang KantinCerdas.</p>${['Cara memesan','Mengambil dan membayar','Pesanan ditolak','Koneksi terputus','Menggunakan asisten'].map(x=>`<div class="settings-row">${icon('help')}<span>${x}</span>${icon('chev')}</div>`).join('')}<div class="banner" style="margin-top:18px">${icon('info')}<div><strong>Pesan dari satu stan</strong><p>Ambil pesanan lalu bayar tunai di konter.</p></div></div>`);if(type==='about')return infoPage('Tentang KantinCerdas',`<div class="empty" style="height:500px;justify-content:flex-start;padding-top:60px"><div style="font-size:24px;font-weight:800;color:var(--brand)">KantinCerdas</div><h3>Pilih lebih cepat, makan lebih tenang</h3><p>Pilih menu, pesan lebih awal, lalu ambil dan bayar di kantin.</p><span class="mode">Versi demo</span><p class="caption" style="margin-top:16px">Seluruh nama, menu, dan pesanan pada tampilan ini adalah data contoh.</p></div>`);if(type==='account')return infoPage('Data akun',`<span class="mode">Akun demo</span><div class="spacer16"></div>${[['Nama','Bu Rina'],['Email','rina@example.com'],['Peran','Pengelola'],['Stan','Dapur Bu Rina']].map(x=>`<div class="summary-row" style="min-height:54px;align-items:center;border-bottom:1px solid var(--outline)"><span class="muted">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}`)}
function infoPage(title,inner){return shell(`<div class="scroll flush">${appbar(title,'',true)}<div class="page">${inner}</div></div>`)}
function logoutDialog(){let base=profile();return base.replace('</section>',dialog('Keluar dari akun?','Kamu akan keluar dari sesi KantinCerdas saat ini.','Batal','Keluar',true)+'</section>')}
function emptyScreen(title,copy,action,{navRole=null,active='home'}={}){return shell(`<div class="scroll"><div class="page"><div class="empty">${emptyIcon('alert')}<h3>${title}</h3><p>${copy}</p><button class="btn primary full">${action}</button></div></div></div>`,{navRole,active})}
function loadingHome(){return shell(`<div class="scroll"><div class="page"><div class="skel-line skeleton" style="width:90px"></div><div class="skel-line skeleton" style="width:150px;margin-top:14px"></div><div class="skeleton" style="height:52px;margin:18px 0 14px"></div><div class="chips"><span class="skeleton" style="width:74px;height:38px"></span><span class="skeleton" style="width:74px;height:38px"></span><span class="skeleton" style="width:74px;height:38px"></span></div><div class="skeleton" style="width:130px;height:20px;margin:22px 0 10px"></div>${skelRow()}${skelRow()}<div class="skeleton" style="width:130px;height:20px;margin:22px 0 10px"></div>${skelRow()}</div></div>`,{navRole:'student',active:'home'})}
function skelRow(){return `<div class="skel-row"><span class="skeleton"></span><div><div class="skel-line skeleton" style="width:80%"></div><div class="skel-line skeleton" style="width:55%"></div><div class="skel-line skeleton" style="width:40%"></div></div></div>`}
function orderSkeleton(){return `<div style="margin-top:18px">${[1,2,3].map(()=>`<div class="order-row"><div class="skel-line skeleton" style="width:45%"></div><div class="skel-line skeleton" style="width:75%"></div><div class="skel-line skeleton" style="width:35%"></div></div>`).join('')}</div>`}
function offlineEmpty(){return shell(`<div class="scroll"><div class="page"><div class="meta">Kantin Kampus</div><h2>Mau makan apa hari ini?</h2><div class="empty" style="height:550px">${emptyIcon('wifi')}<h3>Belum ada data yang bisa ditampilkan</h3><p>Hubungkan perangkat ke internet untuk memuat menu.</p><button class="btn primary full">Coba lagi</button></div></div></div>`,{navRole:'student',active:'home'})}
function photoFailure(){return shell(`<div class="scroll">${appbar('Hasil pencarian')}<div class="page">${searchBox('ayam')}<p class="meta" style="margin:14px 0">3 menu ditemukan</p>${menuRow(menu.ayam,{fallback:true})}${menuRow(menu.geprek)}${menuRow(menu.kecap)}</div></div>`,{navRole:'student',active:'home'})}
function statusActionFailure(){let out=managerDetail('process');return out.replace('<h3>Item pesanan</h3>',`<div class="banner error" style="margin-top:14px">${icon('alert')}<div><strong>Status belum berubah</strong><p>Pesanan tetap Diproses. Coba tandai siap diambil lagi.</p></div></div><h3>Item pesanan</h3>`).replace('Tandai siap diambil','Coba tandai siap diambil')}
function componentBoard(){return `<section class="screen component-board"><div class="board-head"><div><div class="board-brand">KantinCerdas</div><h1>Fondasi visual & komponen</h1><p>Kantin Kampus Praktis · Android · grid 8 dp · target sentuh minimum 48 dp</p></div><span class="mode">F00 · referensi tetap</span></div><div class="board-grid"><div class="board-card"><h3>Token warna</h3><div class="swatches">${[['#FAFAF8','Background'],['#FFFFFF','Surface'],['#F7F3F0','Alt'],['#E85D2A','Brand'],['#C74418','Action'],['#9B341B','Active'],['#251B17','Text'],['#6D5A50','Secondary'],['#DDD6D1','Outline'],['#B3261E','Destructive'],['#2E7D32','Available'],['#F4B740','Accent']].map(x=>`<span class="swatch"><i style="background:${x[0]};border:1px solid #ddd"></i>${x[1]}<br>${x[0]}</span>`).join('')}</div></div><div class="board-card"><h3>Tipografi</h3><div class="type-sample" style="font-size:24px;line-height:32px;font-weight:800"><strong>H1 24/32</strong></div><div class="type-sample" style="font-size:20px;line-height:28px;font-weight:700"><strong>H2 20/28</strong></div><div class="type-sample" style="font-size:18px;line-height:24px;font-weight:700"><strong>Judul 18/24</strong></div><div class="type-sample" style="font-size:16px;line-height:24px">Body 16/24</div><div class="type-sample" style="font-size:14px;line-height:20px">Metadata 14/20</div><div class="measure">Plus Jakarta Sans · regular + bold</div></div><div class="board-card wide"><h3>Row menu & kontrol jumlah</h3>${menuRow(menu.ayam,{qty:1})}</div><div class="board-card wide"><h3>Status pesanan</h3><div class="badge-wrap">${status('waiting','Menunggu konfirmasi')}${status('process','Diproses')}${status('ready','Siap diambil')}${status('done','Selesai')}${status('rejected','Ditolak')}</div><div class="spacer24"></div><h3>Tombol & feedback</h3><div class="button-wrap"><button class="btn primary">Buat pesanan</button><button class="btn secondary">Coba lagi</button><button class="btn destructive">Kosongkan</button><button class="btn disabled">Tidak tersedia</button></div><div class="banner error" style="margin-top:14px">${icon('alert')}<div><strong>Status belum berubah</strong><p>Coba lagi tanpa kehilangan data.</p></div></div></div><div class="board-card"><h3>Input, chip & ikon</h3><label class="form-label">Catatan untuk penjual (opsional)</label><div class="input">Sambal dipisah</div><div class="chips"><button class="chip active selected">Maks. 10 menit</button><button class="chip">Tanpa batas</button></div><div class="button-wrap" style="margin-top:12px"><button class="icon-btn">${icon('search')}</button><button class="icon-btn">${icon('trash')}</button><button class="icon-btn">${icon('x')}</button></div><div class="measure">Glyph 20–24 dp · area sentuh 48 × 48 dp</div></div><div class="board-card"><h3>Navigasi mahasiswa</h3><div class="mini-nav"><span class="active">${icon('home')}<br>Beranda</span><span>${icon('orders')}<br>Pesanan</span><span>${icon('user')}<br>Profil</span></div><h3>Navigasi pengelola</h3><div class="mini-nav"><span class="active">${icon('grid')}<br>Dashboard</span><span>${icon('orders')}<br>Pesanan</span><span>${icon('food')}<br>Menu</span><span>${icon('user')}<br>Profil</span></div></div><div class="board-card wide"><h3>Sticky cart, FAB & coachmark</h3><div style="position:relative;height:150px;border:1px solid var(--outline);border-radius:14px;overflow:hidden">${cartBar()}<button class="fab with-cart-fab" style="bottom:82px">${icon('spark')}</button><div class="coachmark" style="bottom:87px"><strong>Bingung pilih?</strong><p>Aku bantu cari menu.</p><button class="icon-btn close">${icon('x')}</button></div></div></div><div class="board-card"><h3>Snackbar & state</h3><div style="position:relative;height:150px"><div class="snackbar" style="left:0;right:0;bottom:75px"><span>Nasi Telur Dadar dihapus</span><button>Urungkan</button></div><div class="skeleton" style="height:52px;margin-top:6px"></div><p class="measure">Loading tidak bercampur dengan spinner layar.</p></div></div><div class="board-card"><h3>Row pesanan & bottom sheet</h3><div class="order-row" style="padding-top:0"><div class="order-row-head"><h4>KC-027 · Doni</h4>${status('waiting','Menunggu')}</div><div class="order-meta"><span>2 porsi</span><strong>Rp30.000</strong></div></div><div style="background:var(--alt);border-radius:16px 16px 8px 8px;padding:10px 12px;margin-top:12px"><div class="handle"></div><strong style="font-size:12px">Bantu pilih menu</strong><p class="caption">Bottom sheet · radius atas 24 dp</p></div></div></div></section>`}

function renderScreen(id){switch(id){case'F00':return componentBoard();case'M01':return home();case'M02':return home({coach:true});case'M03':return home({cart:true});case'M04':return searchScreen();case'M05':return searchScreen({sheet:true});case'M06':return stall();case'M07':return stall({cart:true});case'M08':return detailMenu();case'M09':return detailMenu({added:true});case'M10':return assistant();case'M11':return assistant('keyboard');case'M12':return assistant('clarify');case'M13':return recommendations();case'M14':return recommendations({cart:true});case'M15':return assistant('fail');case'M16':return recommendations({empty:true});case'M17':return cart();case'M18':return cartOverlay('edit');case'M19':{let x=cart({one:true});return x.replace('</section>',`<div class="snackbar above-footer"><span>Nasi Telur Dadar dihapus</span><button>Urungkan</button></div></section>`)}case'M20':return cartOverlay('clear');case'M21':return changeStall();case'M22':return emptyCart();case'M23':return cart({unavailable:true});case'M24':return checkout();case'M25':return checkout('loading');case'M26':return checkout('failed');case'M27':return checkout('unknown');case'M28':return success();case'M29':return studentOrders();case'M30':return studentOrders({history:true});case'M31':return studentDetail('waiting');case'M32':return studentDetail('process');case'M33':return studentDetail('ready');case'M34':return studentDetail('done');case'M35':return studentDetail('rejected');case'M36':return profile();case'M37':return preferences();case'P01':return dashboard();case'P02':return dashboard(false,true);case'P03':return dashboard(true);case'P04':return managerOrders('new');case'P05':return managerOrders('process');case'P06':return managerOrders('ready');case'P07':return managerOrders('history');case'P08':return managerDetail('new');case'P09':return managerDetail('process');case'P10':return managerDetail('ready');case'P11':return managerDetail('ready','finish');case'P12':return managerDetail('done');case'P13':return managerDetail('new','reject');case'P14':return managerDetail('rejected');case'P15':return managerMenu();case'P16':return managerMenu(true);case'P17':return settings();case'P18':return profile(true);case'U01':return notification('intro');case'U02':return notification('denied');case'U03':return notification('active');case'U04':return support('help');case'U05':return support('about');case'U06':return support('account');case'U07':return logoutDialog();case'U08':return settings(true);case'U09':return preferences(true);case'S01':return loadingHome();case'S02':return searchScreen({empty:true});case'S03':return home({offline:true,cart:true});case'S04':return offlineEmpty();case'S05':return managerOrders('new',false,false,true);case'S06':return stall({closed:true});case'S07':return detailMenu({sold:true});case'S08':return studentDetail('process',true);case'S09':return studentOrders({loading:true});case'S10':return home({failure:true});case'S11':return stall({empty:true});case'S12':return studentOrders({empty:true});case'S13':return managerOrders('new',true);case'S14':return managerMenu(false,true);case'S15':return photoFailure();case'S16':return statusActionFailure();case'S17':return managerOrders('new',false,true);case'Q01':return home({cart:true,width:'w360'});case'Q02':return stall({cart:true,width:'w412'});case'Q03':return home({cart:true,textScale:true,klass:'text150'});case'Q04':return recommendations({cart:true,long:true}).replace('class="screen','class="screen w360 text150');case'Q05':return cart({long:true});case'Q06':{let x=cart({keyboard:true});return x.replace('</section>',keyboardUI()+'</section>')}}return home()}

function init(){const q=new URLSearchParams(location.search);const id=(q.get('screen')||'M01').toUpperCase();const capture=q.get('capture');if(capture){const dims=id==='F00'?[1440,1024]:id==='Q01'||id==='Q04'||id==='Q06'?[360,800]:id==='Q02'?[412,915]:[390,844];const scale=Number(q.get('scale')||1);document.body.className='capture-mode';document.documentElement.style.setProperty('--capture-w',dims[0]*scale+'px');document.documentElement.style.setProperty('--capture-h',dims[1]*scale+'px');document.documentElement.style.setProperty('--capture-scale',scale);document.getElementById('capture-root').innerHTML=renderScreen(id);return}document.getElementById('capture-root').hidden=true;const gallery=document.getElementById('gallery');gallery.hidden=false;const groups={Fondasi:['F00'],Mahasiswa:ids.filter(x=>x[0]==='M'),Pengelola:ids.filter(x=>x[0]==='P'),Pendukung:ids.filter(x=>x[0]==='U'),Sistem:ids.filter(x=>x[0]==='S'),Responsif:ids.filter(x=>x[0]==='Q')};const groupEl=document.getElementById('screen-groups');for(const [name,list] of Object.entries(groups)){groupEl.insertAdjacentHTML('beforeend',`<h3>${name}</h3>${list.map(x=>`<button class="screen-link" data-id="${x}"><strong>${x}</strong><span>${labels[x]}</span></button>`).join('')}`)}let current=ids.indexOf(id)>=0?id:'M01';const preview=document.getElementById('preview-frame');function show(next){current=next;document.querySelectorAll('.screen-link').forEach(b=>b.classList.toggle('active',b.dataset.id===current));preview.innerHTML=renderScreen(current);document.getElementById('gallery-id').textContent=current;document.getElementById('gallery-title').textContent=labels[current];document.getElementById('gallery-count').textContent=`${ids.indexOf(current)+1} dari ${ids.length}`;const file=`screens/${current}_${slug(labels[current])}.png`;document.getElementById('download-screen').href=file;history.replaceState(null,'',`?screen=${current}`)}groupEl.addEventListener('click',e=>{const b=e.target.closest('.screen-link');if(b)show(b.dataset.id)});document.getElementById('prev-screen').onclick=()=>show(ids[(ids.indexOf(current)-1+ids.length)%ids.length]);document.getElementById('next-screen').onclick=()=>show(ids[(ids.indexOf(current)+1)%ids.length]);document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')document.getElementById('prev-screen').click();if(e.key==='ArrowRight')document.getElementById('next-screen').click()});document.getElementById('screen-search').addEventListener('input',e=>{let s=e.target.value.toLowerCase();document.querySelectorAll('.screen-link').forEach(b=>b.hidden=!(`${b.dataset.id} ${labels[b.dataset.id]}`.toLowerCase().includes(s)))});show(current)}
function slug(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
init();
